js=js.replace("init().catch(e=>{window.error=e.stack;throw e});",'''let pending=false;function update(){if(!window.ready||pending)return;pending=true;requestAnimationFrame(async()=>{try{const yaw=Number(document.getElementById('yaw').value)*Math.PI/180;const zoom=Number(document.getElementById('zoom').value);const mode=document.getElementById('mode').value;const width=Math.min(1200,innerWidth),height=Math.min(1100,innerHeight-125);let target=[48,45,42],spanZ=130/zoom,rise=45,dist=260,extra={};if(mode==='facade'){target=[47,61,52];spanZ=36/zoom;rise=12;dist=180}if(mode==='river'){target=[48,17,45];spanZ=78/zoom;rise=35;dist=200;extra={cutY:32}}if(mode==='section'){target=[46,58,48];spanZ=38/zoom;rise=12;extra={cutX:50,cutY:73,minY:47}}let viewYaw=yaw;let eye=[48+Math.sin(viewYaw)*dist,target[1]+rise,44+Math.cos(viewYaw)*dist];if(mode==='top'){target=[48,3,42];eye=[48,400,42];spanZ=108/zoom}await window.render({width,height,spanZ,spanX:spanZ*width/height,eye,target,ortho:true,night:document.getElementById('night').checked,concept:false,...extra});document.getElementById('msg').textContent='NBT 同源几何 · 拖动旋转 · 玻璃及照明为近似预览';}catch(e){window.error=e.stack;document.getElementById('msg').textContent='实时预览不可用：'+e.message}pending=false})}
for(const el of document.querySelectorAll('input,select'))el.addEventListener('input',update);let drag=null;cv.addEventListener('pointerdown',e=>{drag=[e.clientX,Number(document.getElementById('yaw').value)];cv.setPointerCapture(e.pointerId)});cv.addEventListener('pointermove',e=>{if(drag){document.getElementById('yaw').value=(drag[1]+(e.clientX-drag[0])*.5+720)%360;update()}});cv.addEventListener('pointerup',()=>drag=null);window.addEventListener('resize',update);init().then(update).catch(e=>{window.error=e.stack;document.getElementById('msg').textContent='实时预览不可用：'+e.message});''')
